import {clone,I,mul,inverse,bounds,localBox,splitSegment,cubic} from './core.js';
const equal=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const N=b=>[b.w||1,0,0,b.h||1,b.x,b.y];
const geometry=o=>({nodes:clone(o.nodes||[]),closed:o.closed,matrix:clone(o.matrix),component:o.component?clone(o.component):null,modifiers:clone(o.modifiers||[]),semanticEdges:clone(o.semanticEdges||{})});
export function initializeStructure(p){p.garment.shared??={pieces:{},axis:p.centerAxis??350};for(const link of p.garment.links){if(p.garment.shared.pieces[link.key])continue;const views={};for(const side of ['front','back']){const o=p.views[side].find(o=>o.id===link[side]);if(o){o.nodes?.forEach((n,i)=>n.structuralSlot??='n'+i);views[side]={id:o.id,base:geometry(o),box:bounds(o),local:o.nodes?localBox(o):{x:0,y:0,w:1,h:1}};}}if(Object.keys(views).length===2)p.garment.shared.pieces[link.key]={views,transform:I(),offsets:{},overrides:{}};}return p;}
function normalizedOffsets(o,view){const base=view.base.nodes,box=view.local,offsets={};for(const n of o.nodes||[]){const b=base.find(b=>b.structuralSlot===n.structuralSlot);if(!b)continue;const value={};for(const key of ['anchor','in','out']){const q=key==='anchor'?n:n[key],q0=key==='anchor'?b:b[key];if(q){const origin=q0||b;value[key]={x:(q.x-origin.x)/(box.w||1),y:(q.y-origin.y)/(box.h||1)};}else if(q0)value[key]=null;}value.kind=n.kind;offsets[n.structuralSlot]=value;}return offsets;}
export function projectPiece(piece,side,o){if(piece.overrides[side])return;const v=piece.views[side],base=v.base;const normalized=N(v.box);o.matrix=mul(normalized,mul(piece.transform,mul(inverse(normalized),base.matrix)));o.nodes=clone(base.nodes);for(const n of o.nodes){const d=piece.offsets[n.structuralSlot];if(!d)continue;for(const key of ['anchor','in','out']){if(!(key in d))continue;const delta=d[key];if(key==='anchor'){n.x+=delta.x*(v.local.w||1);n.y+=delta.y*(v.local.h||1);}else if(delta){const start=base.nodes.find(b=>b.structuralSlot===n.structuralSlot)[key]||base.nodes.find(b=>b.structuralSlot===n.structuralSlot);n[key]={x:start.x+delta.x*(v.local.w||1),y:start.y+delta.y*(v.local.h||1)};}else delete n[key];}if(d.kind)n.kind=d.kind;}o.closed=base.closed;if(piece.component!==undefined){if(piece.component)o.component=clone(piece.component);else delete o.component;}if(piece.modifiers)o.modifiers=clone(piece.modifiers).map(m=>{if(m.edgeSlots){m.edgeIds=o.nodes.filter(n=>m.edgeSlots.includes(n.structuralSlot)).map(n=>n.edgeId);delete m.edgeSlots;}return m;});}
function adaptTopology(piece,side,o,previous){const v=piece.views[side],other=side==='front'?'back':'front',dest=piece.views[other];if(!previous?.nodes)return;const old=previous.nodes;for(const n of o.nodes){if(n.structuralSlot)continue;const i=o.nodes.indexOf(n),a=o.nodes[(i-1+o.nodes.length)%o.nodes.length],b=o.nodes[(i+1)%o.nodes.length],index=old.findIndex(q=>q.nid===a?.nid);n.structuralSlot='s'+n.nid;if(index<0)continue;let best={d:Infinity,t:.5};for(let k=1;k<100;k++){const q=cubic(old[index],old[(index+1)%old.length],k/100),d=Math.hypot(q.x-n.x,q.y-n.y);if(d<best.d)best={d,t:k/100};}for(const target of [v,dest]){const bi=target.base.nodes.findIndex(q=>q.structuralSlot===a.structuralSlot);if(bi<0)continue;const inserted=splitSegment(target.base,bi,best.t);target.base.nodes[inserted].structuralSlot=n.structuralSlot;}}
const slots=new Set(o.nodes.map(n=>n.structuralSlot));for(const target of [v,dest])target.base.nodes=target.base.nodes.filter(n=>slots.has(n.structuralSlot));}
export function syncStructure(p,before,side){initializeStructure(p);p.garment.shared.axis=p.centerAxis??350;for(const link of p.garment.links){const o=p.views[side].find(o=>o.id===link[side]),prev=before?.views?.[side]?.find(o=>o.id===link[side]),piece=p.garment.shared.pieces[link.key];if(!o||!prev||!piece)continue;if(equal(geometry(o),geometry(prev)))continue;if(p.applyTo==='this'){piece.overrides[side]=geometry(o);if(!p.garment.diverged.includes(link.key))p.garment.diverged.push(link.key);continue;}delete piece.overrides[side];const v=piece.views[side];adaptTopology(piece,side,o,prev);const normalized=N(v.box);piece.transform=mul(inverse(normalized),mul(o.matrix,mul(inverse(v.base.matrix),normalized)));piece.offsets=normalizedOffsets(o,v);if(!equal(o.component,prev.component))piece.component=clone(o.component||null);if(!equal(o.modifiers,prev.modifiers))piece.modifiers=clone(o.modifiers||[]).map(m=>{if(m.edgeIds)m.edgeSlots=o.nodes.filter(n=>m.edgeIds.includes(n.edgeId)||(n.edgeParents||[]).some(id=>m.edgeIds.includes(id))).map(n=>n.structuralSlot);return m;});for(const other of ['front','back']){const dest=p.views[other].find(x=>x.id===piece.views[other].id);if(dest&&other!==side)projectPiece(piece,other,dest);}if(!Object.keys(piece.overrides).length)p.garment.diverged=p.garment.diverged.filter(k=>k!==link.key);p.garment.dimensions[link.key]={width:bounds(o).w,length:bounds(o).h};}}
export function relinkStructure(p,side,id,adopt=true,seen=new Set()){if(seen.has(id))return false;seen.add(id);initializeStructure(p);const link=p.garment.links.find(l=>l[side]===id),piece=link&&p.garment.shared.pieces[link.key];if(!piece)return false;const o=p.views[side].find(o=>o.id===id);if(adopt){const v=piece.views[side],normalized=N(v.box);piece.transform=mul(inverse(normalized),mul(o.matrix,mul(inverse(v.base.matrix),normalized)));piece.offsets=normalizedOffsets(o,v);}piece.overrides={};for(const view of ['front','back'])projectPiece(piece,view,p.views[view].find(o=>o.id===piece.views[view].id));p.garment.diverged=p.garment.diverged.filter(k=>k!==link.key);p.applyTo='both';for(const child of p.views[side].filter(o=>o.attachment?.source===id))relinkStructure(p,side,child.id,adopt,seen);return true;}
export function structureState(p){const pieces=Object.values(p.garment.shared?.pieces||{}).filter(piece=>['front','back'].every(side=>p.views[side].some(o=>o.id===piece.views[side].id)));if(!pieces.length)return 'none';return pieces.some(piece=>Object.keys(piece.overrides).length)?'unlinked':'linked';}

// Authored attachments follow their structural parent's affine change, while
// retaining local shape, parameters and identity. Already-edited children are
// not transformed a second time in the same transaction.
export function syncAttachments(p,before,side){const os=p.views[side],old=before?.views?.[side]||[],done=new Set();for(let pass=0;pass<os.length;pass++){let changed=false;for(const o of os){const parent=o.attachment&&os.find(s=>s.id===o.attachment.source),prev=old.find(s=>s.id===o.id),oldParent=parent&&old.find(s=>s.id===parent.id);if(!parent||!prev||!oldParent||done.has(o.id)||!equal(o.matrix,prev.matrix)||equal(parent.matrix,oldParent.matrix))continue;o.matrix=mul(mul(parent.matrix,inverse(oldParent.matrix)),o.matrix);done.add(o.id);changed=true;}if(!changed)break;}}
